  [/\b\d(?:[ -]?\d){12,18}\b/g, '[card-or-account-number]'],
  [/\+?\(?\d[\d\s().-]{7,}\d/g, '[phone]'],
  [/\bhttps?:\/\/[^\s)]+/gi, '[link]'],
  [/\b(?:Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{8,}/gi, '[credential]'],
  [/\b(?:api[_-]?key|password|passwd|secret|token)\s*[:=]\s*\S+/gi, '[credential]'],
